def call_with_timeout(func, args, timeout=0.5):
    """Run func(*args) in daemon thread, return (completed, result)."""
    box = {}
    def target():
        try:
            box["result"] = func(*args)
        except BaseException as e:
            box["error"] = e
    t = threading.Thread(target=target, daemon=True)
    t.start()
    t.join(timeout)
    if t.is_alive():
        return (False, None)
    if "error" in box:
        raise box["error"]
    return (True, box.get("result"))

@given(
    n=st.integers(min_value=-5, max_value=5),
    k=st.integers(min_value=0, max_value=6),
)
def test_exact_nonnegative_powers_are_true(n, k):
    x = n ** k  # Python semantics, n**0 == 1 including 0**0
    # 0**0 == 1 case is x==1 which is covered; skip ambiguous 0-base
    # generation that hangs is avoided because x == n**k terminates;
    # but filter the hanging-prone (n==0 and x not in (0,1)) -- cannot happen here
    # since x is exactly 0 or 1 when n==0.
    assert is_simple_power(x, n) is True
